            name = v.get('name', v.get('id', ''))
            input_props[name] = var_to_schema_prop(v)

    output_props = {}
    for v in all_vars:
        if not v.get('elementId'):
            ltag = v.tag.split('}')[1] if '}' in v.tag else v.tag
            if ltag in ('output', 'inputOutput'):
